import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Identify strong univariate predictors
    strong = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical':
            continue  # Skip clinical features for now
        t_stat, p_val = stats.ttest_ind(feats.x[:,i][feats.y==1], feats.x[:,i][feats.y==0])
        if abs(t_stat) > 5.0 and p_val < 0.001:
            strong.append((fid, abs(t_stat)))

    # Sort by strength
    strong.sort(key=lambda x: x[1], reverse=True)

    # Select top candidates, avoiding near-duplicates
    drivers = []
    used = set()
    for fid, _ in strong:
        if len(drivers) >= MAX_DRIVERS:
            break
        # Check if this feature is correlated with any already selected
        is_correlated = False
        for d_fid in drivers:
            col_a = feats.column(d_fid)
            col_b = feats.column(fid)
            corr = np.corrcoef(feats.x[:,col_a], feats.x[:,col_b])[0,1]
            if abs(corr) > 0.6:
                is_correlated = True
                break
        if not is_correlated:
            drivers.append(fid)
            used.add(fid)

    # Limit to at most 4 drivers as per checker report
    if len(drivers) > 4:
        drivers = drivers[:4]

    # Build columns and products
    columns = drivers[:]
    products = []

    # Add interaction terms between top features
    for i, a in enumerate(drivers):
        for b in drivers[i+1:]:
            # Only add if both features are present
            if a in feats.ids and b in feats.ids:
                products.append((a,b))

    # Simple weighted score using top features
    loadings = {}
    for i, fid in enumerate(feats.ids):
        if fid in drivers:
            # Weight by effect size (t-statistic)
            t_stat, _ = stats.ttest_ind(feats.x[:,i][feats.y==1], feats.x[:,i][feats.y==0])
            loadings[fid] = abs(t_stat)

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

